import { API, graphqlOperation } from "aws-amplify";
import { update_list_email_templates } from "@/graphql/mutations.js";
import SnackBar from "@/components/SnackBar.vue";
import { VueEditor } from "vue3-editor";
export default {
  name: "InvoiceTemplate",
  components: {
    SnackBar,
    VueEditor
  },
  data() {
    return {
      saving: false,
      isFormValid: false,
      windowHeight: 0,
      SnackBarComponent: {},
      // VueEditor properties
      customToolbar: [["bold", "italic", "underline", "strike"], ["blockquote", "code-block"], [{
        header: 1
      }, {
        header: 2
      }], [{
        list: "ordered"
      }, {
        list: "bullet"
      }], [{
        script: "sub"
      }, {
        script: "super"
      }], [{
        indent: "-1"
      }, {
        indent: "+1"
      }], [{
        direction: "rtl"
      }], [{
        size: ["small", false, "large", "huge"]
      }], [{
        header: [1, 2, 3, 4, 5, 6, false]
      }], [{
        color: []
      }, {
        background: []
      }], [{
        font: []
      }], [{
        align: []
      }], ["clean"], ["link", "image"]],
      editorOptions: {
        placeholder: "Enter email content...",
        theme: "snow"
      },
      // Template data
      templateName: "Invoice Template",
      emailSubject: "Invoice - {{invoice_number}}",
      emailContent: "Dear {{customer_name}},\n\nPlease find attached the invoice for your recent purchase.\n\n**Invoice Details:**\n- Invoice Number: {{invoice_number}}\n- Invoice Date: {{invoice_date}}\n- Due Date: {{due_date}}\n- Total Amount: {{total_amount}}\n- Tax Amount: {{tax_amount}}\n\n**Payment Instructions:**\n- Bank: {{bank_name}}\n- Account: {{account_number}}\n- Reference: {{invoice_number}}\n\n**Payment Terms:**\n{{payment_terms}}\n\nPlease ensure payment is made by the due date to avoid any late payment charges.\n\nIf you have any questions about this invoice, please contact our accounts team.\n\nThank you for your business!\n\nBest regards,\n{{sender_name}}\n{{company_name}}",
      // Available variables for template
      availableVariables: [{
        key: "{{customer_name}}",
        label: "Customer Name"
      }, {
        key: "{{invoice_number}}",
        label: "Invoice Number"
      }, {
        key: "{{invoice_date}}",
        label: "Invoice Date"
      }, {
        key: "{{due_date}}",
        label: "Due Date"
      }, {
        key: "{{total_amount}}",
        label: "Total Amount"
      },
      // { key: "{{tax_amount}}", label: "Tax Amount" },
      // { key: "{{bank_name}}", label: "Bank Name" },
      // { key: "{{account_number}}", label: "Account Number" },
      // { key: "{{payment_terms}}", label: "Payment Terms" },
      // { key: "{{sender_name}}", label: "Sender Name" },
      {
        key: "{{company_name}}",
        label: "Company Name"
      }, {
        key: "{{company_address}}",
        label: "Company Address"
      }, {
        key: "{{company_phone}}",
        label: "Company Phone"
      }, {
        key: "{{company_email}}",
        label: "Company Email"
      }],
      quill: null
    };
  },
  mounted() {
    this.windowHeight = window.innerHeight - 150;
    this.loadTemplate();
  },
  methods: {
    async loadTemplate() {
      try {
        let result = await API.graphql(graphqlOperation(update_list_email_templates, {
          input: {
            action_type: "LIST",
            email_template_type: "SALE"
          }
        }));
        // console.log("Result:", result);
        let response = JSON.parse(result.data.update_list_email_templates);
        if (response.Status === "SUCCESS" && response.data.length > 0) {
          const emailTemplate = response.data[0].email_template;
          this.emailSubject = emailTemplate.subject || "";
          this.emailContent = emailTemplate.body || "";
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error fetching template",
          timeout: 5000,
          Top: true
        };
      }
    },
    goBack() {
      this.$emit("backAction");
    },
    onEditorReady(quill) {
      this.quill = quill;
    },
    onEditorInput(html) {
      this.emailContent = html;
    },
    insertVariable(variable) {
      if (this.quill) {
        const range = this.quill.getSelection();
        if (range) {
          this.quill.insertText(range.index, variable);
        } else {
          this.quill.insertText(this.quill.getLength(), variable);
        }
      }
    },
    async saveTemplate() {
      // Validate form before saving
      const {
        valid
      } = await this.$refs.templateForm.validate();
      if (!valid) {
        this.$toast?.error("Please fix validation errors before saving");
        return;
      }
      this.saving = true;
      try {
        let result = await API.graphql(graphqlOperation(update_list_email_templates, {
          input: {
            action_type: "UPDATE",
            email_template_type: "SALE",
            email_template: this.all_data_template()
          }
        }));
        let response = JSON.parse(result.data.update_list_email_templates);
        if (response.Status === "SUCCESS") {
          this.saving = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error saving template",
          timeout: 5000,
          Top: true
        };
      } finally {
        this.saving = false;
      }
    },
    all_data_template() {
      var data = {
        body: this.emailContent,
        subject: this.emailSubject,
        cc: []
      };
      return JSON.stringify(data);
    }
  }
};
